import{_ as s,c as a,b as p,o as e}from"./app-CAz8fl6k.js";const t={};function c(o,n){return e(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="arraybuffer、typedarray-与-dataview-详解" tabindex="-1"><a class="header-anchor" href="#arraybuffer、typedarray-与-dataview-详解"><span>ArrayBuffer、TypedArray 与 DataView 详解</span></a></h1><hr><h5 id="arraybuffer-原始二进制数据缓冲区" tabindex="-1"><a class="header-anchor" href="#arraybuffer-原始二进制数据缓冲区"><span>ArrayBuffer - 原始二进制数据缓冲区</span></a></h5><p>[补充说明]：ArrayBuffer 表示通用的、固定长度的原始二进制数据缓冲区。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建 ArrayBuffer [修正术语：Arraybuffer → ArrayBuffer]</span></span>
<span class="line"><span class="token keyword">const</span> buffer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">16</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 创建16字节的缓冲区</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>buffer<span class="token punctuation">.</span>byteLength<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 16</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 不能直接操作 ArrayBuffer，需要通过视图操作</span></span>
<span class="line"><span class="token comment">// console.log(buffer[0]); // 错误：不能直接访问</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="typedarray-类型化数组视图" tabindex="-1"><a class="header-anchor" href="#typedarray-类型化数组视图"><span>TypedArray - 类型化数组视图</span></a></h5><p>[补充说明]：TypedArray 提供了对 ArrayBuffer 的类型化视图访问。 在 JavaScript 中，<strong>TypedArray（类型化数组）</strong> 是一组用于处理二进制数据的数组-like对象，专为高效操作原始二进制数据而设计。它们与普通数组（<code>Array</code>）的主要区别在于：<strong>存储的数据类型固定</strong>（如整数、浮点数等），且<strong>长度不可变</strong>，因此性能更高，尤其适合处理大量二进制数据（如音频、图像、网络协议数据等）。</p><h5 id="typedarray-的特点" tabindex="-1"><a class="header-anchor" href="#typedarray-的特点"><span>TypedArray 的特点</span></a></h5><ol><li><strong>固定数据类型</strong>：每个元素的类型在创建时确定（如 8位整数、32位浮点数等），避免了普通数组的动态类型转换开销。</li><li><strong>固定长度</strong>：创建时需指定长度，创建后无法通过 <code>push</code>/<code>pop</code> 等方法改变（类似 C 语言的数组）。</li><li><strong>存储原始二进制数据</strong>：直接映射到内存中的二进制数据缓冲区（<code>ArrayBuffer</code>），读写效率远高于普通数组。</li><li><strong>不继承 <code>Array.prototype</code></strong>：不支持 <code>Array</code> 的部分方法（如 <code>concat</code>、<code>splice</code>），但支持索引访问和 <code>length</code> 属性。</li></ol><h5 id="常见的-typedarray-类型" tabindex="-1"><a class="header-anchor" href="#常见的-typedarray-类型"><span>常见的 TypedArray 类型</span></a></h5><p>JavaScript 提供了多种 TypedArray 构造函数，对应不同的数据类型和字节长度：</p><table><thead><tr><th>构造函数</th><th>元素类型</th><th>字节长度</th><th>取值范围（示例）</th></tr></thead><tbody><tr><td><code>Int8Array</code></td><td>8位有符号整数</td><td>1</td><td>-128 到 127</td></tr><tr><td><code>Uint8Array</code></td><td>8位无符号整数</td><td>1</td><td>0 到 255</td></tr><tr><td><code>Uint8ClampedArray</code></td><td>8位无符号整数（截断）</td><td>1</td><td>超出范围时自动截断为 0 或 255</td></tr><tr><td><code>Int16Array</code></td><td>16位有符号整数</td><td>2</td><td>-32768 到 32767</td></tr><tr><td><code>Uint16Array</code></td><td>16位无符号整数</td><td>2</td><td>0 到 65535</td></tr><tr><td><code>Int32Array</code></td><td>32位有符号整数</td><td>4</td><td>-2³¹ 到 2³¹-1</td></tr><tr><td><code>Uint32Array</code></td><td>32位无符号整数</td><td>4</td><td>0 到 2³²-1</td></tr><tr><td><code>Float32Array</code></td><td>32位浮点数（单精度）</td><td>4</td><td>约 ±3.4×10³⁸</td></tr><tr><td><code>Float64Array</code></td><td>64位浮点数（双精度）</td><td>8</td><td>约 ±1.8×10³⁰⁸</td></tr></tbody></table><p><strong>TypedArray 的使用示例</strong> TypedArray 必须基于 ArrayBuffer（原始二进制数据缓冲区）创建，直接创建会在内部自动创建，<code>ArrayBuffer</code> 是一块原始的内存区域，TypedArray 则是对这块内存的“视图”（按指定类型解析数据）。</p><h5 id="_1-基本创建与使用" tabindex="-1"><a class="header-anchor" href="#_1-基本创建与使用"><span>1. 基本创建与使用</span></a></h5><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 1. 创建一个 16 字节的 ArrayBuffer（内存缓冲区）</span></span>
<span class="line"><span class="token keyword">const</span> buffer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">16</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 2. 创建 TypedArray 视图（以 32位整数解析 buffer）</span></span>
<span class="line"><span class="token keyword">const</span> int32View <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Int32Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 3. 长度由缓冲区大小和元素字节长度决定：16字节 / 4字节/元素 = 4个元素</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>int32View<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 4</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 4. 操作元素（索引访问）</span></span>
<span class="line">int32View<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">;</span></span>
<span class="line">int32View<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">200</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>int32View<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Int32Array(4) [100, 200, 0, 0]</span></span>
<span class="line"><span class="token comment">// 查看对应的原始二进制数据缓冲区</span></span>
<span class="line"><span class="token comment">// ArrayBuffer {</span></span>
<span class="line"><span class="token comment">//   [Uint8Contents]: &lt;64 00 00 00 c8 00 00 00 00 00 00 00 00 00 00 00&gt;,</span></span>
<span class="line"><span class="token comment">//   byteLength: 16</span></span>
<span class="line"><span class="token comment">// }</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 5. 不同视图解析同一块缓冲区（二进制数据的灵活解读）</span></span>
<span class="line"><span class="token keyword">const</span> uint8View <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>uint8View<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Uint8Array(16) [100, 0, 0, 0, 200, 0, 0, 0, 0, ...]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>64 00 00 00 c8 00 00 00 00 00 00 00 00 00 00 00 低位—————————————————高位 对应16个字节，int32是用32个位，就是4个字节，也就是四个一组，转换为10进制： 对应100,200,0,0</p><h5 id="_2-直接初始化" tabindex="-1"><a class="header-anchor" href="#_2-直接初始化"><span>2. 直接初始化</span></a></h5><p>也可以直接通过长度或数组初始化 TypedArray（内部会对应的==自动创建== ==<code>ArrayBuffer</code>==）：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 用长度初始化（8个 16位整数）</span></span>
<span class="line"><span class="token keyword">const</span> int16Arr <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Int16Array</span><span class="token punctuation">(</span><span class="token number">8</span><span class="token punctuation">)</span></span>
<span class="line">int16Arr<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">32767</span> <span class="token comment">// 最大16位有符号整数</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>int16Arr<span class="token punctuation">.</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// ArrayBuffer {</span></span>
<span class="line"><span class="token comment">//   [Uint8Contents]: &lt;ff 7f 00 00 00 00 00 00 00 00 00 00 00 00 00 00&gt;,</span></span>
<span class="line"><span class="token comment">//   byteLength: 16</span></span>
<span class="line"><span class="token comment">// }</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 用数组初始化</span></span>
<span class="line"><span class="token keyword">const</span> float64Arr <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Float64Array</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1.5</span><span class="token punctuation">,</span> <span class="token number">2.5</span><span class="token punctuation">,</span> <span class="token number">3.5</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>float64Arr<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token comment">// 2.5</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>float64Arr<span class="token punctuation">.</span>buffer<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// ArrayBuffer {</span></span>
<span class="line"><span class="token comment">//   [Uint8Contents]: &lt;00 00 00 00 00 00 f8 3f 00 00 00 00 00 00 04 40 00 00 00 00 00 00 0c 40&gt;,</span></span>
<span class="line"><span class="token comment">//   byteLength: 24</span></span>
<span class="line"><span class="token comment">// }</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="typedarray-与普通数组的核心区别" tabindex="-1"><a class="header-anchor" href="#typedarray-与普通数组的核心区别"><span>TypedArray 与普通数组的核心区别</span></a></h5><table><thead><tr><th>特性</th><th>TypedArray</th><th>普通数组（<code>Array</code>）</th></tr></thead><tbody><tr><td>元素类型</td><td>固定（如 <code>Int32</code>、<code>Float64</code>）</td><td>动态（可混合各种类型）</td></tr><tr><td>长度</td><td>固定（创建后不可变）</td><td>可变（可通过 <code>push</code> 等方法修改）</td></tr><tr><td>存储方式</td><td>二进制缓冲区（高效）</td><td>动态对象存储（有额外开销）</td></tr><tr><td>继承关系</td><td>不继承 <code>Array.prototype</code></td><td>继承 <code>Array.prototype</code></td></tr><tr><td>适用场景</td><td>二进制数据处理（音视频等）</td><td>通用数据存储与操作</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 不同类型的 TypedArray 视图</span></span>
<span class="line"><span class="token keyword">const</span> int8Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Int8Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// 8位有符号整数</span></span>
<span class="line"><span class="token keyword">const</span> uint8Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 8位无符号整数</span></span>
<span class="line"><span class="token keyword">const</span> int16Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Int16Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 16位有符号整数</span></span>
<span class="line"><span class="token keyword">const</span> uint16Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint16Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 16位无符号整数</span></span>
<span class="line"><span class="token keyword">const</span> int32Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Int32Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 32位有符号整数</span></span>
<span class="line"><span class="token keyword">const</span> uint32Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint32Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 32位无符号整数</span></span>
<span class="line"><span class="token keyword">const</span> float32Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Float32Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 32位浮点数</span></span>
<span class="line"><span class="token keyword">const</span> float64Array <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Float64Array</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 64位浮点数</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 直接创建带数据的 TypedArray</span></span>
<span class="line"><span class="token keyword">const</span> dataArray <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>dataArray<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 5</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>dataArray<span class="token punctuation">.</span>byteLength<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 5</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="dataview-灵活的数据访问视图" tabindex="-1"><a class="header-anchor" href="#dataview-灵活的数据访问视图"><span>DataView - 灵活的数据访问视图</span></a></h5><p>[补充说明]：DataView 提供了更灵活的低级接口来读写 ArrayBuffer 中的数据。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建 DataView</span></span>
<span class="line"><span class="token keyword">const</span> buffer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">const</span> view <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DataView</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 设置和读取数据（可以指定字节偏移和端序）</span></span>
<span class="line">view<span class="token punctuation">.</span><span class="token function">setInt8</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">127</span><span class="token punctuation">)</span> <span class="token comment">// 在位置0写入8位有符号整数</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>view<span class="token punctuation">.</span>buffer<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// ArrayBuffer { [Uint8Contents]: &lt;7f 00 00 00&gt;, byteLength: 4 }</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 小端序写入16位无符号整数</span></span>
<span class="line">view<span class="token punctuation">.</span><span class="token function">setUint16</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">65534</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span> </span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>view<span class="token punctuation">.</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// ArrayBuffer { [Uint8Contents]: &lt;7f 00 fe ff&gt;, byteLength: 4 }</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>view<span class="token punctuation">.</span><span class="token function">getInt8</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 127 因为就一位所以不分高低了</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>view<span class="token punctuation">.</span><span class="token function">getUint16</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 65534 (小端序读取)从低位（fe）到高位（ff）</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>view<span class="token punctuation">.</span><span class="token function">getUint16</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 65279 (大端序读取)反之</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="内存布局与字节序" tabindex="-1"><a class="header-anchor" href="#内存布局与字节序"><span>内存布局与字节序</span></a></h5><p>[补充说明]：理解内存布局对于二进制数据处理至关重要。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 演示字节序（Endianness）的影响</span></span>
<span class="line"><span class="token keyword">const</span> testBuffer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> view1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DataView</span><span class="token punctuation">(</span>testBuffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 写入32位整数</span></span>
<span class="line">view1<span class="token punctuation">.</span><span class="token function">setInt32</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0x12345678</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 大端序</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span>testBuffer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [0x12, 0x34, 0x56, 0x78]</span></span>
<span class="line"></span>
<span class="line">view1<span class="token punctuation">.</span><span class="token function">setInt32</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0x12345678</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 小端序</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span>testBuffer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [0x78, 0x56, 0x34, 0x12]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="实际应用示例" tabindex="-1"><a class="header-anchor" href="#实际应用示例"><span>==实际应用示例==</span></a></h5><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 示例：处理二进制文件格式（如图像文件头）</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">parsePNGHeader</span><span class="token punctuation">(</span><span class="token parameter">buffer</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> view <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DataView</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 检查PNG文件签名</span></span>
<span class="line">    <span class="token keyword">const</span> signature <span class="token operator">=</span> view<span class="token punctuation">.</span><span class="token function">getUint32</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>signature <span class="token operator">!==</span> <span class="token number">0x89504E47</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;不是有效的PNG文件&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 读取图像尺寸</span></span>
<span class="line">    <span class="token keyword">const</span> width <span class="token operator">=</span> view<span class="token punctuation">.</span><span class="token function">getUint32</span><span class="token punctuation">(</span><span class="token number">16</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">const</span> height <span class="token operator">=</span> view<span class="token punctuation">.</span><span class="token function">getUint32</span><span class="token punctuation">(</span><span class="token number">20</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> width<span class="token punctuation">,</span> height <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 示例：创建和操作二进制数据</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">createBinaryData</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> buffer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">12</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">const</span> view <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DataView</span><span class="token punctuation">(</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 写入不同类型的数据</span></span>
<span class="line">    view<span class="token punctuation">.</span><span class="token function">setFloat32</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token constant">PI</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 32位浮点数（小端序）</span></span>
<span class="line">    view<span class="token punctuation">.</span><span class="token function">setUint16</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">,</span> <span class="token number">1000</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// 16位无符号整数（大端序）</span></span>
<span class="line">    view<span class="token punctuation">.</span><span class="token function">setInt8</span><span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">,</span> <span class="token operator">-</span><span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                 <span class="token comment">// 8位有符号整数</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">return</span> buffer<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="性能优化与使用场景" tabindex="-1"><a class="header-anchor" href="#性能优化与使用场景"><span>性能优化与使用场景</span></a></h5><table><thead><tr><th>数据类型</th><th>适用场景</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>ArrayBuffer</strong></td><td>原始二进制数据存储</td><td>内存高效</td><td>不能直接操作</td></tr><tr><td><strong>TypedArray</strong></td><td>类型化数据处理</td><td>高性能，类型安全</td><td>固定数据类型</td></tr><tr><td><strong>DataView</strong></td><td>混合数据类型访问</td><td>灵活，支持端序控制</td><td>性能稍低</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 性能比较：TypedArray vs DataView</span></span>
<span class="line"><span class="token keyword">const</span> testData <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">1000000</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用 TypedArray（更快）</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span><span class="token string">&#39;TypedArray&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> uint8View <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Uint8Array</span><span class="token punctuation">(</span>testData<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> uint8View<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    uint8View<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">=</span> i <span class="token operator">%</span> <span class="token number">256</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">timeEnd</span><span class="token punctuation">(</span><span class="token string">&#39;TypedArray&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用 DataView（更灵活但稍慢）</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">time</span><span class="token punctuation">(</span><span class="token string">&#39;DataView&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> dataView <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DataView</span><span class="token punctuation">(</span>testData<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> testData<span class="token punctuation">.</span>byteLength<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    dataView<span class="token punctuation">.</span><span class="token function">setUint8</span><span class="token punctuation">(</span>i<span class="token punctuation">,</span> i <span class="token operator">%</span> <span class="token number">256</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">timeEnd</span><span class="token punctuation">(</span><span class="token string">&#39;DataView&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="与-blob-的转换" tabindex="-1"><a class="header-anchor" href="#与-blob-的转换"><span>与 Blob 的转换</span></a></h5><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// ArrayBuffer 转 Blob</span></span>
<span class="line"><span class="token keyword">const</span> arrayBuffer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayBuffer</span><span class="token punctuation">(</span><span class="token number">1024</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> blob <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Blob</span><span class="token punctuation">(</span><span class="token punctuation">[</span>arrayBuffer<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;application/octet-stream&#39;</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Blob 转 ArrayBuffer</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">blobToArrayBuffer</span><span class="token punctuation">(</span><span class="token parameter">blob</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">await</span> blob<span class="token punctuation">.</span><span class="token function">arrayBuffer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 现代浏览器支持的方法</span></span>
<span class="line">    <span class="token comment">// 或使用 FileReader</span></span>
<span class="line">    <span class="token comment">// return new Promise((resolve) =&gt; {</span></span>
<span class="line">    <span class="token comment">//     const reader = new FileReader();</span></span>
<span class="line">    <span class="token comment">//     reader.onloadend = () =&gt; resolve(reader.result);</span></span>
<span class="line">    <span class="token comment">//     reader.readAsArrayBuffer(blob);</span></span>
<span class="line">    <span class="token comment">// });</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h1 id="blob、file-与-object-url-详解" tabindex="-1"><a class="header-anchor" href="#blob、file-与-object-url-详解"><span>Blob、File 与 Object URL 详解</span></a></h1><hr><h5 id="blob-对象" tabindex="-1"><a class="header-anchor" href="#blob-对象"><span>Blob 对象</span></a></h5><p>[补充说明]：Blob（Binary Large Object）表示不可变的原始数据类文件对象。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 创建 Blob 对象</span></span>
<span class="line"><span class="token keyword">let</span> debug <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;Dano&#39;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">let</span> str <span class="token operator">=</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>debug<span class="token punctuation">)</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>str<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// {&quot;name&quot;:&quot;Dano&quot;} 15个字符</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 语法：new Blob(array, options)</span></span>
<span class="line"><span class="token keyword">let</span> blob <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Blob</span><span class="token punctuation">(</span><span class="token punctuation">[</span>str<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;application/json&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 获取 Blob 信息</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>blob<span class="token punctuation">)</span> <span class="token comment">// Blob { size: 15, type: &#39;application/json&#39; }</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>blob<span class="token punctuation">.</span>size<span class="token punctuation">)</span> <span class="token comment">// Blob 大小（字节）15</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>blob<span class="token punctuation">.</span>type<span class="token punctuation">)</span> <span class="token comment">// MIME 类型 application/json</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在JavaScript中，字符的存储方式取决于字符串的编码类型。JavaScript字符串使用UTF-16编码，这意味着每个字符通常使用==2个字节==（16位）存储。但是，对于Unicode中超出基本多文种平面（BMP）的字符（即码点大于0xFFFF的字符），它们需要使用两个16位码元（即==4个字节==）来表示，这称为代理对（surrogate pair）。</p><p>因此，一般情况下，一个字符占用2个字节，但对于辅助平面中的字符，则占用4个字节。</p><div class="language-JavaScript line-numbers-mode" data-highlighter="prismjs" data-ext="JavaScript"><pre><code class="language-JavaScript"><span class="line">// 创建 Blob 对象</span>
<span class="line">let debug = { name: &#39;Dano😊&#39; }</span>
<span class="line">let str = JSON.stringify(debug)</span>
<span class="line">console.log(str)</span>
<span class="line"></span>
<span class="line">let blob = new Blob([str], { type: &#39;application/json&#39; })</span>
<span class="line"></span>
<span class="line">// 获取 Blob 信息</span>
<span class="line">console.log(blob) </span>
<span class="line">console.log(blob.size) </span>
<span class="line">console.log(blob.type) </span>
<span class="line">// {&quot;name&quot;:&quot;Dano😊&quot;}</span>
<span class="line">// Blob { size: 19, type: &#39;application/json&#39; }</span>
<span class="line">// 19</span>
<span class="line">// application/json</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="file-对象" tabindex="-1"><a class="header-anchor" href="#file-对象"><span>File 对象</span></a></h5><p>[补充说明]：File 对象继承自 Blob，表示文件数据。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 通过 input 获取 File 对象</span></span>
<span class="line"><span class="token keyword">const</span> fileInput <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;fileInput&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">fileInput<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;change&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> file <span class="token operator">=</span> event<span class="token punctuation">.</span>target<span class="token punctuation">.</span>files<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>file<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 文件名</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>file<span class="token punctuation">.</span>size<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 文件大小</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>file<span class="token punctuation">.</span>type<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 文件类型</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>file<span class="token punctuation">.</span>lastModified<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 最后修改时间</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 创建 File 对象</span></span>
<span class="line"><span class="token keyword">const</span> file <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>debug<span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string">&#39;user.json&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;application/json&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">lastModified</span><span class="token operator">:</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="filereader-读取文件内容" tabindex="-1"><a class="header-anchor" href="#filereader-读取文件内容"><span>FileReader 读取文件内容</span></a></h5><p>[修正代码]：FileReader是浏览器独有的API在Node中</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> json <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;Dano😊&#39;</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> file <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>json<span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string">&#39;user.json&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;application/json&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">lastModified</span><span class="token operator">:</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>file<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// File {</span></span>
<span class="line"><span class="token comment">//   size: 19,</span></span>
<span class="line"><span class="token comment">//   type: &#39;application/json&#39;,</span></span>
<span class="line"><span class="token comment">//   name: &#39;user.json&#39;,</span></span>
<span class="line"><span class="token comment">//   lastModified: 1757595534532</span></span>
<span class="line"><span class="token comment">// }</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">FileReader</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">reader<span class="token punctuation">.</span><span class="token function">readAsArrayBuffer</span><span class="token punctuation">(</span>file<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">reader<span class="token punctuation">.</span><span class="token function-variable function">onload</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> arrayBuffer <span class="token operator">=</span> e<span class="token punctuation">.</span>target<span class="token punctuation">.</span>result</span>
<span class="line">    <span class="token comment">// 将 ArrayBuffer 转换为字符串</span></span>
<span class="line">    <span class="token keyword">const</span> decoder <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">TextDecoder</span><span class="token punctuation">(</span><span class="token string">&#39;utf-8&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> jsonString <span class="token operator">=</span> decoder<span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>arrayBuffer<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> parsedJson <span class="token operator">=</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span>jsonString<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 显示结果</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>file<span class="token punctuation">,</span> arrayBuffer<span class="token punctuation">,</span> parsedJson<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">reader<span class="token punctuation">.</span><span class="token function-variable function">onerror</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&#39;读取文件时出错: &#39;</span><span class="token punctuation">,</span> e<span class="token punctuation">.</span>target<span class="token punctuation">.</span>error<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>![Pasted image 20250911211549](../../../../../../_assets/6dacdad-Pasted image 20250911211549.png)</p><h5 id="object-url" tabindex="-1"><a class="header-anchor" href="#object-url"><span>Object URL</span></a></h5><p>[补充说明]：创建指向Blob/File对象的临时URL</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> debug <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;Domo&#39;</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> blob <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Blob</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>debug<span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;application/json&#39;</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 创建下载链接</span></span>
<span class="line">    <span class="token keyword">let</span> a <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;a&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    a<span class="token punctuation">.</span>download <span class="token operator">=</span> <span class="token string">&#39;user.json&#39;</span><span class="token punctuation">;</span></span>
<span class="line">    a<span class="token punctuation">.</span>rel <span class="token operator">=</span> <span class="token string">&#39;noopener&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 安全优化</span></span>
<span class="line">    a<span class="token punctuation">.</span>href <span class="token operator">=</span> <span class="token constant">URL</span><span class="token punctuation">.</span><span class="token function">createObjectURL</span><span class="token punctuation">(</span>blob<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 模拟点击下载</span></span>
<span class="line">    a<span class="token punctuation">.</span><span class="token function">click</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 释放URL资源 [补充说明]</span></span>
<span class="line">    <span class="token constant">URL</span><span class="token punctuation">.</span><span class="token function">revokeObjectURL</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span>href<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="base64-与-dataurl" tabindex="-1"><a class="header-anchor" href="#base64-与-dataurl"><span>Base64 与 DataURL</span></a></h5><p>[补充说明]：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// Data URL 格式：data:[&lt;mediatype&gt;][;base64],&lt;data&gt;</span></span>
<span class="line"><span class="token keyword">const</span> dataURL <span class="token operator">=</span> <span class="token string">&#39;data:application/json;base64,eyJuYW1lIjoiRG9tbyJ9&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Base64 编码解码</span></span>
<span class="line"><span class="token keyword">const</span> base64Encoded <span class="token operator">=</span> <span class="token function">btoa</span><span class="token punctuation">(</span><span class="token string">&#39;Hello World&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 编码</span></span>
<span class="line"><span class="token keyword">const</span> base64Decoded <span class="token operator">=</span> <span class="token function">atob</span><span class="token punctuation">(</span><span class="token string">&#39;SGVsbG8gV29ybGQ=&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 解码</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Blob 转 Base64</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">blobToBase64</span><span class="token punctuation">(</span><span class="token parameter">blob</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">resolve</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">const</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">FileReader</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        reader<span class="token punctuation">.</span><span class="token function-variable function">onloadend</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">resolve</span><span class="token punctuation">(</span>reader<span class="token punctuation">.</span>result<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        reader<span class="token punctuation">.</span><span class="token function">readAsDataURL</span><span class="token punctuation">(</span>blob<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Base64 和 Data URL 不是同一个东西。</strong> 它们的关系非常密切，但扮演着完全不同的角色。 简单来说：</p><ul><li><strong>Base64 是一种编码方式</strong>（把二进制数据变成文本）。</li><li><strong>Data URL 是一种 URL 方案</strong>（一种特殊格式的网址）。</li><li><strong>Data URL 经常使用 Base64 编码作为其数据部分</strong>。</li></ul><h5 id="data-url" tabindex="-1"><a class="header-anchor" href="#data-url"><span>Data URL</span></a></h5><ul><li><strong>是什么</strong>：一种特殊格式的URL（统一资源定位符），它的协议头不是 <code>http:</code> 或 <code>https:</code>，而是 <code>data:</code>。它允许将数据直接内嵌在文档中，而无需从外部服务器加载。</li><li><strong>结构</strong>：一个完整的Data URL有固定的格式，它包含了<strong>元数据</strong>和<strong>数据本身</strong>。 <code>data:[&amp;lt;mediatype&amp;gt;][;base64],&amp;lt;data&amp;gt;</code></li><li><strong><code>data:</code></strong>：协议头，表明这是一个Data URL。</li><li><strong><code>[&amp;lt;mediatype&amp;gt;]</code></strong>：可选的MIME类型，告诉浏览器数据的格式是什么。例如 <code>image/png</code>, <code>text/css</code>, <code>application/pdf</code>。如果省略，默认为 <code>text/plain</code>。</li><li><strong><code>[;base64]</code></strong>：可选的标识符。如果存在，表示后面的 <code>&amp;lt;data&amp;gt;</code> 部分是经过 <strong>Base64编码</strong>的。如果不存在，则表示数据是URL编码的文本（通常仅适用于纯文本或SVG）。</li><li><strong><code>,</code></strong>：分隔符，前面是元信息，后面是数据本体。</li><li><strong><code>&amp;lt;data&amp;gt;</code></strong>：实际的数据内容。如果使用了 <code>;base64</code>，这里就是Base64编码后的字符串。</li></ul><p>例子： 一个PNG图片的Data URL可能长这样： <code>data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUAAAAFCAYAAACNbyblAAAAHElEQVQI12P4//8/w38GIAXDIBKE0DHxgljNBAAO9TXL0Y4OHwAAAABJRU5ErkJggg==</code></p><h5 id="关系" tabindex="-1"><a class="header-anchor" href="#关系"><span>关系</span></a></h5><ul><li><strong>依赖关系</strong>：Data URL <strong>可以</strong>使用Base64编码，但不是必须的。对于二进制数据（如图片、PDF），必须使用Base64编码才能放入Data URL。对于纯文本（如CSS或SVG代码），可以不使用Base64，直接写入。</li><li><strong>协作方式</strong>：Data URL 提供了一个完整的“包装”，告诉浏览器“这里面是什么类型的数据”以及“数据是如何编码的”。而Base64编码则负责完成实际的数据转换工作，将二进制数据变成Data URL能够安全使用的文本形式。</li></ul><h5 id="内存管理最佳实践" tabindex="-1"><a class="header-anchor" href="#内存管理最佳实践"><span>内存管理最佳实践</span></a></h5><p>[补充说明]：</p><ol><li><strong>及时释放 Object URL</strong>：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> objectURL <span class="token operator">=</span> <span class="token constant">URL</span><span class="token punctuation">.</span><span class="token function">createObjectURL</span><span class="token punctuation">(</span>blob<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 使用完成后立即释放</span></span>
<span class="line"><span class="token constant">URL</span><span class="token punctuation">.</span><span class="token function">revokeObjectURL</span><span class="token punctuation">(</span>objectURL<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li><strong>大文件处理</strong>：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 使用切片处理大文件</span></span>
<span class="line"><span class="token keyword">const</span> chunkSize <span class="token operator">=</span> <span class="token number">1024</span> <span class="token operator">*</span> <span class="token number">1024</span><span class="token punctuation">;</span> <span class="token comment">// 1MB</span></span>
<span class="line"><span class="token keyword">let</span> offset <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">while</span> <span class="token punctuation">(</span>offset <span class="token operator">&lt;</span> file<span class="token punctuation">.</span>size<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> chunk <span class="token operator">=</span> file<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span>offset<span class="token punctuation">,</span> offset <span class="token operator">+</span> chunkSize<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">// 处理分片...</span></span>
<span class="line">    offset <span class="token operator">+=</span> chunkSize<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="使用场景对比" tabindex="-1"><a class="header-anchor" href="#使用场景对比"><span>使用场景对比</span></a></h5><table><thead><tr><th>技术</th><th>适用场景</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>Object URL</strong></td><td>临时显示或下载文件</td><td>无需服务器，性能好</td><td>需要手动释放内存</td></tr><tr><td><strong>Data URL</strong></td><td>小文件内联</td><td>自包含，无需额外请求</td><td>体积增大33%，不适合大文件</td></tr><tr><td><strong>FileReader</strong></td><td>读取文件内容</td><td>多种读取方式</td><td>异步操作，需要回调</td></tr></tbody></table><h1 id="mime" tabindex="-1"><a class="header-anchor" href="#mime"><span>MIME</span></a></h1><hr><p><strong>MIME 类型</strong>（也称为<strong>媒体类型</strong>或<strong>内容类型</strong>）是一种标准，用来表示文档、文件或字节流的<strong>性质和格式</strong>。 它的全称是 <strong>Multipurpose Internet Mail Extensions</strong>（多用途互联网邮件扩展）。顾名思义，它最初是为了在电子邮件中支持非 ASCII 字符和附件而设计的，但现在它被广泛应用在互联网的各个领域，尤其是 HTTP 协议中。</p><p><strong>MIME 类型就是答案。</strong> 服务器在发送数据之前，会在 HTTP 响应的头部（Headers）中包含一个 <code>Content-Type</code> 字段，告诉浏览器（或其他客户端）正在发送的数据是什么类型。</p><p>Content-Type: text/html; charset=UTF-8 这行代码告诉浏览器：“接下来要发送的内容是 HTML 文本，使用的字符编码是 UTF-8”。浏览器收到这个信号后，就会启动 HTML 解析器来渲染页面。 如果没有 MIME 类型，浏览器只能靠猜测来处理数据，结果会非常不可靠和安全。</p><p>MIME 类型由<strong>类型（type）</strong> 和<strong>子类型（subtype）</strong> 两部分组成，中间由一条<strong>正斜杠 <code>/</code></strong> 连接。 格式：<code>type/subtype</code></p><h5 id="_1-类型-type" tabindex="-1"><a class="header-anchor" href="#_1-类型-type"><span>1. 类型（Type）</span></a></h5><p>代表大的类别，说明数据的一般类型。常见的顶级类型有：</p><ul><li><p><code>text</code>： 文本文件，人类可读的文字内容。</p><ul><li>例如：<code>text/plain</code>, <code>text/html</code>, <code>text/css</code></li></ul></li><li><p><code>image</code>： 图像文件或图形数据。</p><ul><li>例如：<code>image/jpeg</code>, <code>image/png</code>, <code>image/gif</code></li></ul></li><li><p><code>audio</code>： 音频或音乐数据。</p><ul><li>例如：<code>audio/mpeg</code>, <code>audio/wav</code></li></ul></li><li><p><code>video</code>： 视频或动态图像数据。</p><ul><li>例如：<code>video/mp4</code>, <code>video/webm</code></li></ul></li><li><p><code>application</code>： 二进制数据或不属于其他类别的数据。通常是需要由应用程序处理的文件。</p><ul><li>例如：<code>application/pdf</code>, <code>application/json</code>, <code>application/javascript</code></li></ul></li><li><p><code>multipart</code>： 由多个部分组成的数据，每个部分可以有自己独立的类型。常用于电子邮件或表单提交。</p><ul><li>例如：<code>multipart/form-data</code></li></ul></li><li><p><code>font</code>： 字体文件。</p><ul><li>例如：<code>font/woff2</code>, <code>font/ttf</code></li></ul></li></ul><h5 id="_2-子类型-subtype" tabindex="-1"><a class="header-anchor" href="#_2-子类型-subtype"><span>2. 子类型（Subtype）</span></a></h5><p>代表特定类型中的具体格式。它精确地指定了是哪种 <code>text</code> 或哪种 <code>image</code>。 例如，同是 <code>text</code> 类型，<code>text/plain</code> 是纯文本，而 <code>text/html</code> 是 HTML 文档。</p><h5 id="常见-mime-类型示例" tabindex="-1"><a class="header-anchor" href="#常见-mime-类型示例"><span>常见 MIME 类型示例</span></a></h5><table><thead><tr><th>文件格式</th><th>MIME 类型</th><th>说明</th></tr></thead><tbody><tr><td><code>.html</code></td><td><code>text/html</code></td><td>HTML 文档</td></tr><tr><td><code>.css</code></td><td><code>text/css</code></td><td>CSS 样式表</td></tr><tr><td><code>.js</code></td><td><code>application/javascript</code></td><td>JavaScript 文件</td></tr><tr><td><code>.json</code></td><td><code>application/json</code></td><td>JSON 数据</td></tr><tr><td><code>.png</code></td><td><code>image/png</code></td><td>PNG 图像</td></tr><tr><td><code>.jpg</code> / <code>.jpeg</code></td><td><code>image/jpeg</code></td><td>JPEG 图像</td></tr><tr><td><code>.pdf</code></td><td><code>application/pdf</code></td><td>Adobe PDF 文档</td></tr><tr><td><code>.zip</code></td><td><code>application/zip</code></td><td>ZIP 压缩档案</td></tr><tr><td><code>.mp3</code></td><td><code>audio/mpeg</code></td><td>MP3 音频</td></tr><tr><td><code>.mp4</code></td><td><code>video/mp4</code></td><td>MP4 视频</td></tr></tbody></table><h5 id="重要参数-charset" tabindex="-1"><a class="header-anchor" href="#重要参数-charset"><span>重要参数：<code>charset</code></span></a></h5><p>对于一些文本类型的文件，经常需要指定一个重要的参数——<strong>字符编码（character set）</strong>。这用 <code>charset</code> 来表示，与主类型用分号 <code>;</code> 分隔。</p><ul><li><strong>示例：</strong> <code>text/html; charset=UTF-8</code></li><li><strong>作用：</strong> 告诉浏览器应该使用哪种字符编码来解读文本，防止出现乱码。对于现代 Web 开发，最常用的就是 <code>UTF-8</code>。</li></ul><h5 id="在实际中的应用" tabindex="-1"><a class="header-anchor" href="#在实际中的应用"><span>在实际中的应用</span></a></h5><ol><li><strong>HTTP 协议</strong>： 如上所述，在 HTTP 请求和响应的头部中，<code>Content-Type</code> 字段至关重要。</li><li><strong>电子邮件</strong>： 用于标识邮件正文和附件的格式。</li><li><strong>文件系统</strong>： 某些操作系统会用 MIME 类型来关联打开文件的默认应用程序。</li><li><strong><code>&amp;lt;link&amp;gt;</code> 和 <code>&amp;lt;script&amp;gt;</code> 标签</strong>： 在 HTML 中，你可以指定引入资源的类型。 &lt;link rel=&quot;stylesheet&quot; type=&quot;text/css&quot; href=&quot;theme.css&quot;&gt; &lt;script type=&quot;application/javascript&quot; src=&quot;app.js&quot;&gt;&lt;/script&gt; （注意：在现代 HTML5 中，<code>type</code> 属性对于 CSS 和 JavaScript 通常可以省略，因为它们已是默认值。）</li></ol>`,90)])])}const i=s(t,[["render",c]]),u=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/%E7%8E%B0%E4%BB%A3JS%E6%95%99%E7%A8%8B_%E9%98%AE%E4%B8%80%E5%B3%B0ES6/5%E7%89%B9%E6%AE%8A%E5%86%85%E5%BB%BA%E5%AF%B9%E8%B1%A1/%E4%BA%8C%E8%BF%9B%E5%88%B6%E4%B8%8E%E6%96%87%E4%BB%B6%E8%AF%BB%E5%8F%96/%E4%BA%8C%E8%BF%9B%E5%88%B6.html","title":"ArrayBuffer、TypedArray 与 DataView 详解","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/三件套/JS/现代JS教程&阮一峰ES6/5特殊内建对象/二进制与文件读取/二进制.md"}');export{i as comp,u as data};
